# CMC Analytica guide: cross-sectional studies and case reports. A4 PDF. Own words; official guidelines cited, not copied.
import html
e=html.escape
YEL="url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 200 40' preserveAspectRatio='none'><path d='M3 9 Q60 2 120 6 T197 4 L199 15 Q196 28 198 35 Q120 40 60 37 T4 38 L1 24 Q4 16 3 9 Z' fill='%23FFE14D' fill-opacity='.92'/></svg>\")"
FOOT='CMC Analytica · Calicut Medical College · College Union · 2026–2027'
LOGO='../../../assets/cmc-analytica-logo.png'
CSS=f'''@font-face{{font-family:Bricolage;src:url(../../../bricolage.woff2);font-weight:200 800}}@font-face{{font-family:Mono;src:url(../../../essays/fonts/mono-normal.woff2)}}
@page{{size:A4;margin:0}}*{{box-sizing:border-box;margin:0;padding:0}}body{{background:#888;font-family:'Times New Roman',Times,serif;color:#111}}
.pg{{width:794px;height:1123px;position:relative;overflow:hidden;background:#fff;padding:70px 64px 80px;page-break-after:always;margin:0 auto 20px}}
.top{{position:absolute;left:64px;right:64px;top:30px;display:flex;justify-content:space-between;font:400 11px Mono,monospace;letter-spacing:.1em;color:#20558A;padding-bottom:6px;border-bottom:3px double #20558A}}
.ft{{position:absolute;left:64px;right:64px;bottom:26px;display:flex;justify-content:space-between;font:400 10.5px Mono,monospace;color:#666;border-top:1px solid #999;padding-top:8px}}
.kick{{font:500 12px Mono,monospace;letter-spacing:.12em;color:#B3261E;margin-top:10px}}
h1,h2{{font-family:Bricolage,Arial,sans-serif;font-weight:800;letter-spacing:-.03em;line-height:1.04}}h1{{font-size:50px;margin-top:14px}}h2{{font-size:34px;margin-top:12px}}h3{{font:800 19px Bricolage,Arial;margin-top:22px;color:#20558A}}
mark{{background-image:{YEL};background-size:100% 82%;background-position:0 85%;background-repeat:no-repeat;background-color:transparent;color:inherit;padding:0 .12em}}
p{{font-size:16.5px;line-height:1.5;margin-top:12px}}p.lead{{font-size:19.5px;line-height:1.45}}ul.b{{margin:10px 0 0 20px}}ul.b li{{font-size:16.5px;line-height:1.45;margin-top:6px}}
.step{{display:grid;grid-template-columns:44px 1fr;gap:14px;padding:16px 0;border-bottom:1px solid #bbb}}.step:first-of-type{{border-top:2px solid #111;margin-top:12px}}
.num{{width:38px;height:34px;font:800 20px/34px Bricolage;text-align:center;background-size:100% 100%;background-repeat:no-repeat}}
.n1{{background-image:{YEL}}}.n2{{background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 200 40' preserveAspectRatio='none'><path d='M3 9 Q60 2 120 6 T197 4 L199 15 Q196 28 198 35 Q120 40 60 37 T4 38 L1 24 Q4 16 3 9 Z' fill='%238BF0C7'/></svg>")}}.n3{{background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 200 40' preserveAspectRatio='none'><path d='M3 9 Q60 2 120 6 T197 4 L199 15 Q196 28 198 35 Q120 40 60 37 T4 38 L1 24 Q4 16 3 9 Z' fill='%23FF9EC4'/></svg>")}}.n4{{background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 200 40' preserveAspectRatio='none'><path d='M3 9 Q60 2 120 6 T197 4 L199 15 Q196 28 198 35 Q120 40 60 37 T4 38 L1 24 Q4 16 3 9 Z' fill='%237FDFFF'/></svg>")}}
.step b{{font:800 18.5px Bricolage,Arial;display:block}}.step p{{margin-top:5px;font-size:15.5px}}
.story{{margin-top:6px;border-left:4px solid #FFB300;padding:2px 0 2px 10px;font-style:italic;font-size:15px;line-height:1.45;color:#333}}.story:before{{content:'OUR STORY  ';font:500 10px Mono,monospace;letter-spacing:.1em;color:#B3261E;font-style:normal}}
.box{{border:2px solid #111;padding:14px 16px;margin-top:18px}}.box.y{{background:#FFF7CC}}.box h4{{font:500 11px Mono,monospace;letter-spacing:.1em;color:#B3261E}}
.src{{font:400 12px Mono,monospace;color:#555;margin-top:12px;line-height:1.5}}
table{{border-collapse:collapse;width:100%;margin-top:12px;font:400 14px Arial;border-top:3px solid #111;border-bottom:3px solid #111}}th{{text-align:left;padding:7px 6px;font:500 10.5px Mono,monospace;letter-spacing:.06em;border-bottom:1.5px solid #111}}td{{padding:9px 6px;border-bottom:1px solid #ccc;vertical-align:top}}td.e{{height:26px}}
.cols{{display:grid;grid-template-columns:1fr 1fr;gap:18px}}.chk li{{list-style:none;font-size:15.5px;line-height:1.45;margin-top:9px;padding-left:22px;position:relative}}.chk li:before{{content:'';position:absolute;left:0;top:3px;width:12px;height:12px;border:2px solid #20558A;border-radius:3px}}
.care{{display:grid;grid-template-columns:34px 1fr;gap:8px;padding:9px 0;border-bottom:1px solid #ccc;font-size:15px;line-height:1.4}}.care b{{font:800 14px Bricolage;color:#20558A}}.care span{{font:700 15px Arial}}
.ref{{font-size:14.5px;line-height:1.45;margin-top:14px;padding-left:16px;text-indent:-16px}}
'''
def pg(n,total,inner,top='CROSS-SECTIONAL STUDIES AND CASE REPORTS · A CMC ANALYTICA GUIDE'):
    return f'<section class="pg"><div class="top"><span>{top}</span><span>{n}/{total}</span></div>{inner}<div class="ft"><span>{FOOT}</span><span>{n:02d}</span></div></section>'
def step(i,t,body,story=None,cls=None):
    c=cls or f'n{(i-1)%4+1}'
    return f'<div class="step"><div class="num {c}">{i}</div><div><b>{t}</b><p>{body}</p>'+(f'<div class="story">{story}</div>' if story else '')+'</div></div>'
P=[]
# 1 COVER
P.append(f'''<section class="pg"><div class="top"><span>A CMC ANALYTICA GUIDE</span><span>1/12</span></div>
<img src="{LOGO}" style="height:190px;margin-top:60px;display:block"><div class="kick" style="margin-top:34px">FOR UNDERGRADUATES · FREE GUIDE</div>
<h1 style="font-size:56px">How to do a <mark>cross-sectional study</mark> and a <mark>case report.</mark></h1>
<p class="lead" style="margin-top:20px;max-width:560px">Step by step, with what we did, what worked, what we got wrong, and where the official guidelines are.</p>
<div style="position:absolute;left:64px;bottom:140px"><div style="font:800 22px Bricolage">Dr. Sidharth Narayanan <span style="font:400 13px Mono;color:#555">· 2020 MBBS batch</span></div><div style="font:800 22px Bricolage;margin-top:8px">Dr. Jerin James <span style="font:400 13px Mono;color:#555">· 2020 MBBS batch</span></div></div>
<div class="ft"><span>{FOOT}</span><span>01</span></div></section>''')
# 2 WHY
P.append(pg(2,12,f'''<div class="kick">WHY THIS GUIDE EXISTS</div><h2>Two hungry undergrads <mark>who knew nothing.</mark></h2>
<p class="lead">We were two undergraduates with a mountain of data and nobody to teach us how research works. That study is why we realised we needed a forum to understand research and actually learn the basics. That is the idea behind CMC Analytica.</p>
<p>This guide is the one we wish we had. It is part guide and part story: each step comes with what we actually did, so you can see where it goes right and where it goes wrong.</p>
<div class="box y"><h4>HOW TO USE IT</h4><ul class="b"><li><b>Part A</b> (pages 3 to 7): the cross-sectional study. Our NCD survey among medical students, which never became a paper.</li><li><b>Part B</b> (pages 8 to 10): the case report. Ours was published after a rejection.</li><li><b>Pages 11 and 12:</b> one-page checklists, and the official guidelines to read next.</li></ul></div>
<div class="box"><h4>A NOTE ON THE GUIDELINES</h4><p style="margin-top:6px">The reporting guidelines (CARE, STROBE) and the WHO STEPS manual belong to their authors. We explain them in our own words, cite them, and point you to the official documents. Always use the official checklist for your final paper.</p></div>
<h3>Which design do you need?</h3>
<table><tr><th>YOU WANT TO</th><th>USE A</th><th>EXAMPLE</th></tr><tr><td>Know how common something is in a group, at one point in time</td><td><b>Cross-sectional study</b></td><td>Risk factors for non-communicable diseases among medical students</td></tr><tr><td>Describe one unusual patient in detail</td><td><b>Case report</b></td><td>A rare tumour, with imaging, pathology and a literature review</td></tr></table>'''))
# 3 A intro
P.append(pg(3,12,f'''<div class="kick">PART A · THE CROSS-SECTIONAL STUDY</div><h2>A <mark>snapshot</mark> of a group.</h2>
<p class="lead">You study a population at one point in time. It tells you how common something is (prevalence). It cannot tell you what caused what.</p>
<svg viewBox="0 0 640 170" style="width:100%;margin-top:14px"><line x1="10" y1="140" x2="630" y2="140" stroke="#999" stroke-width="2"/><rect x="270" y="20" width="100" height="120" rx="10" fill="#E8F0F9" stroke="#2F6FA8" stroke-width="3"/><g fill="#2F6FA8">{''.join(f'<circle cx="{x}" cy="{y}" r="6"/>' for x,y in [(292,50),(320,40),(345,70),(298,92),(330,110),(352,120),(300,125),(322,78)])}</g><text x="320" y="14" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#20558A">ONE MOMENT</text><text x="130" y="86" font-family="Arial" font-size="13" fill="#888">before</text><text x="480" y="86" font-family="Arial" font-size="13" fill="#888">after</text><text x="10" y="162" font-family="Arial" font-size="12" fill="#888">TIME</text></svg>
<div class="cols"><div><h3>It is good for</h3><ul class="b"><li>Prevalence of a condition or risk factor</li><li>Describing a population</li><li>Planning services and screening</li><li>Generating questions for later studies</li></ul></div><div><h3>It cannot</h3><ul class="b"><li>Show what came first, the exposure or the outcome</li><li>Prove cause</li><li>Follow people over time</li></ul></div></div>
<div class="box y"><h4>OUR STUDY</h4><p style="margin-top:6px">Risk factors for non-communicable diseases among medical students in a college in North Kerala. We used the WHO STEPS protocol and collected data at the college health camps. It earned us the KUHS UG Research Award. We never published it. The next four pages show every step, and the mistakes.</p></div>'''))
# 4-5 steps
S1=[('Narrow down the topic','Decide who you are studying, how you will study them, which guidelines or parent studies already exist, and which tool you can actually administer.','For us, the work was in narrowing the topic. We chose non-communicable diseases.'),
('Find a framework and a tool','Look for existing templates with ready questionnaires. A validated tool beats one you invent.','We searched for templates and stumbled upon the WHO STEPS protocol. We started building the questionnaire.'),
('Write the protocol','Question and objectives, population and sample, tools and variables, analysis plan, ethics. Page 6 has a skeleton.','Our protocol was ready. But WHO STEPS needs anthropometric and biochemical data too, and we were clueless about how to collect it.'),
('Find the data opportunity','Look for events or settings where the data is already being collected.','The then College Union decided to run a health camp. A lot of tests would be done. Why waste that?')]
S2=[('Clear the Institutional Research Committee','Submit the full protocol. Expect corrections. Answer each one and resubmit until you are cleared for the ethics committee.','The head of the IRC sent corrections. We made them. After periodic reviews, we were cleared for the IEC.'),
('Clear the Institutional Ethics Committee','Submit a request with the printouts the committee asks for, and attend the meeting where members review the proposal. Do not collect data before approval.','We took a lot of printouts and submitted a request to the IEC. I went to the meeting where all members reviewed our proposal.'),
('Collect the data','Plan who collects what, where and when. Keep records tidy from the first participant.','We went to each health camp, guided students through it and measured their physical parameters, with the help of the whole college. We ended up with a mountain of data.'),
('Analyse it','Plan the analysis before you collect. Know the software. Find someone who can teach it.','We had no ChatGPT or Claude then. We worked in SPSS, Excel and Google Sheets, and depended on Dr. Ashik, who taught us SPSS at every point. It took another year and a half.')]
P.append(pg(4,12,'<div class="kick">PART A · STEPS 1 TO 4</div><h2>From topic to <mark>opportunity.</mark></h2>'+''.join(step(i+1,a,b,c) for i,(a,b,c) in enumerate(S1))+'<div class="src">Reference: WHO. The WHO STEPwise approach to noncommunicable disease risk factor surveillance (STEPS). who.int</div>'))
P.append(pg(5,12,'<div class="kick">PART A · STEPS 5 TO 8</div><h2>Approvals, data, <mark>analysis.</mark></h2>'+''.join(step(i+5,a,b,c) for i,(a,b,c) in enumerate(S2))+'<div class="src">Reference: ICMR. National Ethical Guidelines for Biomedical and Health Research Involving Human Participants, 2017.</div>'))
# 6 protocol skeleton
P.append(pg(6,12,f'''<div class="kick">PART A · TEMPLATE</div><h2>A protocol <mark>skeleton.</mark></h2><p>Use these headings to draft yours. Fill each with one short paragraph, then take it to your guide.</p>
<table><tr><th style="width:30%">SECTION</th><th>WHAT TO WRITE</th></tr>
<tr><td><b>Title</b></td><td>The population, the setting and the design, in one line.</td></tr>
<tr><td><b>Background</b></td><td>What is known (your literature review) and the gap you will address.</td></tr>
<tr><td><b>Objectives</b></td><td>One primary objective. Add secondary objectives only if you will analyse them.</td></tr>
<tr><td><b>Study design and setting</b></td><td>Cross-sectional, where, and when.</td></tr>
<tr><td><b>Population and sample</b></td><td>Who is included and excluded. How many, and how you chose them (sample size and sampling method).</td></tr>
<tr><td><b>Tools and variables</b></td><td>The questionnaire or instrument, with its source. List every variable and how it is defined.</td></tr>
<tr><td><b>Data collection</b></td><td>Who collects what, where, and how you protect the data.</td></tr>
<tr><td><b>Analysis plan</b></td><td>Which statistics, which software, which tables. See the next page.</td></tr>
<tr><td><b>Ethics</b></td><td>Consent, confidentiality, risks, and which committees approve it.</td></tr>
<tr><td><b>Timeline and team</b></td><td>Who does what, by when. Name your guide.</td></tr></table>
<div class="box y"><h4>THE MISTAKE WE MADE</h4><p style="margin-top:6px">We collected a lot, and planned too little for the analysis. A smaller dataset with a clear plan beats a mountain you cannot structure.</p></div>'''))
# 7 analysis plan
P.append(pg(7,12,f'''<div class="kick">PART A · TEMPLATE</div><h2>Draw the tables <mark>first.</mark></h2><p>Before you collect a single row, sketch the empty tables your paper will need. If a table needs a variable you did not collect, you will know now, not later.</p>
<h3>Table 1 · Characteristics of participants</h3><table><tr><th>VARIABLE</th><th>CATEGORY</th><th>n</th><th>%</th></tr><tr><td>Sex</td><td>Male / Female</td><td class="e"></td><td></td></tr><tr><td>Year of study</td><td>Phase / year</td><td class="e"></td><td></td></tr><tr><td>Age</td><td>Mean (SD)</td><td class="e"></td><td></td></tr></table>
<h3>Table 2 · Prevalence of the main outcome</h3><table><tr><th>OUTCOME OR RISK FACTOR</th><th>n</th><th>% (95% CI)</th></tr><tr><td>(your primary outcome)</td><td class="e"></td><td></td></tr><tr><td>(a second outcome)</td><td class="e"></td><td></td></tr></table>
<h3>Table 3 · Comparison across groups</h3><table><tr><th>VARIABLE</th><th>GROUP A</th><th>GROUP B</th><th>p-value</th></tr><tr><td>(e.g. outcome by sex)</td><td class="e"></td><td></td><td></td></tr></table>
<div class="box"><h4>BEFORE YOU COLLECT, CHECK</h4><ul class="b"><li>Every table variable is in your tool.</li><li>Every variable has a definition and a coding plan.</li><li>You know which software and which test.</li><li>A guide has reviewed the plan.</li></ul></div>'''))
# 8 reporting STROBE + B intro
P.append(pg(8,12,f'''<div class="kick">PART A · REPORTING</div><h2>Write it up with <mark>STROBE.</mark></h2>
<p class="lead">STROBE is the international reporting guideline for observational studies, including cross-sectional ones. Journals expect you to follow it and often ask for the checklist.</p>
<p>In our own words, a cross-sectional paper should cover:</p>
<ul class="b"><li><b>Title and abstract:</b> say it is a cross-sectional study, and summarise what you did and found.</li><li><b>Introduction:</b> the background, and your objectives.</li><li><b>Methods:</b> design, setting, participants, variables, data sources and tools, ways you handled bias, how you chose the sample size, and the statistical methods.</li><li><b>Results:</b> how many took part, who they were, the main results, and any extra analyses.</li><li><b>Discussion:</b> key results, limitations, how to interpret them, and whether they apply to others.</li><li><b>Other:</b> funding.</li></ul>
<div class="box y"><h4>USE THE OFFICIAL CHECKLIST</h4><p style="margin-top:6px">This is a summary. The 22-item checklist is on the STROBE website, with versions for cross-sectional, cohort and case-control studies. The authors hold the copyright, so download it from the source and cite them.</p></div>
<div class="src">Reference: von Elm E, Altman DG, Egger M, Pocock SJ, Gotzsche PC, Vandenbroucke JP. The Strengthening the Reporting of Observational Studies in Epidemiology (STROBE) Statement: guidelines for reporting observational studies. BMJ 2007;335:806-808. strobe-statement.org</div>
<h3>What we got wrong, in one line</h3><p>We had the data and the approvals. We did not have a paper plan, or a briefing for our guide on how to structure it. <i>We did have a guide who had published. We did not orient the project with them well enough.</i></p>'''))
# 9 Part B intro + steps
CR=[('Find the case','Rare cases turn up in any big tertiary care hospital. Ask a guide who knows an interesting one.','Our guide, Dr. Sanudev, told us about an interesting case.'),
('Get consent','Talk to the patient, usually at follow-up, and take written consent for publishing their details.','We got consent by talking to the patient as they came for follow-up.'),
('Collect what exists','Most case reports are retrospective. Gather the old records, the pathology slides and blocks, and the imaging.','We collected the histopathology slides and radiology images, and the old patient records. We also had next-generation sequencing (NGS) done.'),
('Tabulate and review the literature','Put the data together. Review existing cases. What makes yours different, and what makes it stand out?','We reviewed existing cases and wrote and rewrote the paper many times.'),
('Submit, and expect rejection','Choose a journal that publishes case reports. If it is rejected, make the corrections and send it again. Answer every reviewer comment, one by one.','The first time around, it was rejected. We corrected it and sent it again. We answered the reviewers one by one. It took almost a year to be published.')]
P.append(pg(9,12,'<div class="kick">PART B · THE CASE REPORT</div><h2>One patient, <mark>told well.</mark></h2><p class="lead">A case report is the detailed account of one patient, usually rare or instructive. It is the easier design to start with, if you have a guide and a case.</p>'+''.join(step(i+1,a,b,c) for i,(a,b,c) in enumerate(CR))+'<div class="src">Our case report: Indian J Med Paediatr Oncol, April 2025. A metastatic solitary fibrous tumour of the parapharyngeal region, with review of literature.</div>',top='PART B · THE CASE REPORT · A CMC ANALYTICA GUIDE'))
# 10 CARE
CARE=[('1','Title','Say it is a case report and name the key feature.'),('2','Key words','A few terms that help people find it.'),('3','Abstract','Introduction, the case, and the main takeaway.'),('4','Introduction','Why this case is worth reporting, with references.'),('5','Patient information','Who the patient is, main concerns, relevant history.'),('6','Clinical findings','What you found on examination.'),('7','Timeline','The sequence of events, ideally as a figure or table.'),('8','Diagnostic assessment','Tests done, challenges, reasoning.'),('9','Therapeutic intervention','What was done, how, and any changes.'),('10','Follow-up and outcomes','How the patient did, results, any unexpected events.'),('11','Discussion','Strengths and limitations, the literature, your reasoning, the takeaway.'),('12','Patient perspective','What the patient shared, where appropriate.'),('13','Informed consent','Confirmation that consent was obtained.')]
P.append(pg(10,12,'<div class="kick">PART B · REPORTING</div><h2>Structure it with <mark>CARE.</mark></h2><p>CARE is the international guideline for reporting case reports. These are its section headings, with a one-line note in our own words.</p>'+''.join(f'<div class="care"><b>{n}</b><div><span>{t}.</span> {d}</div></div>' for n,t,d in CARE)+'<div class="src">Reference: Gagnier JJ, Kienle G, Altman DG, Moher D, Sox H, Riley D; the CARE Group. The CARE Guidelines: Consensus-based Clinical Case Reporting Guideline Development. BMJ Case Rep 2013;2013:bcr2013201554. Explanation and Elaboration: J Clin Epidemiol 2017. Please cite them, and use the official checklist from care-statement.org or the EQUATOR Network.</div>',top='PART B · THE CASE REPORT · A CMC ANALYTICA GUIDE'))
# 11 checklists
P.append(pg(11,12,'''<div class="kick">ONE-PAGE CHECKLISTS</div><h2>Before you <mark>start.</mark></h2>
<div class="cols"><div><h3>Cross-sectional study</h3><ul class="chk"><li>One clear question and objective</li><li>A guide who has published, briefed on the plan</li><li>A framework or validated tool</li><li>Protocol written, with sample size and sampling</li><li>Tables drawn before data collection</li><li>Institutional Research Committee cleared</li><li>Institutional Ethics Committee cleared</li><li>Consent process ready</li><li>Software and analysis owner decided</li><li>STROBE checklist downloaded</li></ul></div>
<div><h3>Case report</h3><ul class="chk"><li>A rare or instructive case</li><li>A guide who knows the case</li><li>Written consent from the patient</li><li>Records, slides and imaging collected</li><li>Timeline drawn</li><li>Literature review done</li><li>What makes this case different, stated</li><li>CARE checklist followed</li><li>Journal chosen</li><li>Ready for rejection and reviewer comments</li></ul></div></div>
<div class="box y"><h4>IF YOU ARE INSIDE AN INSTITUTION</h4><p style="margin-top:6px">Find a guide: a faculty member in the right department who agrees to guide your work, and brief them early on the plan and the paper. If you are outside an institution, the next article in the series covers what to do.</p></div>
<div class="box"><h4>REMEMBER</h4><ul class="b"><li>A small question beats a mountain of data.</li><li>Plan the analysis, and the paper, before you collect.</li><li>Rejection is part of it. Correct, and resubmit.</li></ul></div>'''))
# 12 references
P.append(pg(12,12,f'''<div class="kick">READ THE ORIGINALS</div><h2>Guidelines and <mark>references.</mark></h2>
<p>We explained these in our own words. For anything you submit, read the official documents and cite them.</p>
<div class="ref"><b>CARE</b> (case reports). Gagnier JJ, Kienle G, Altman DG, Moher D, Sox H, Riley D; the CARE Group. The CARE Guidelines: Consensus-based Clinical Case Reporting Guideline Development. BMJ Case Rep 2013;2013:bcr2013201554 (also J Clin Epidemiol 2014;67(1):46-51). Explanation and Elaboration: J Clin Epidemiol 2017. care-statement.org</div>
<div class="ref"><b>STROBE</b> (observational studies, including cross-sectional). von Elm E, Altman DG, Egger M, Pocock SJ, Gotzsche PC, Vandenbroucke JP. The Strengthening the Reporting of Observational Studies in Epidemiology (STROBE) Statement: guidelines for reporting observational studies. BMJ 2007;335:806-808 (also Ann Intern Med 2007;147:573-577). strobe-statement.org</div>
<div class="ref"><b>WHO STEPS.</b> World Health Organization. The WHO STEPwise approach to noncommunicable disease risk factor surveillance. who.int</div>
<div class="ref"><b>ICMR.</b> Indian Council of Medical Research. National Ethical Guidelines for Biomedical and Health Research Involving Human Participants, 2017. icmr.gov.in</div>
<div class="ref"><b>EQUATOR Network.</b> A library of reporting guidelines for health research. equator-network.org</div>
<div class="box y" style="margin-top:22px"><h4>ABOUT THIS GUIDE</h4><p style="margin-top:6px">Written by Dr. Sidharth Narayanan and Dr. Jerin James, 2020 MBBS batch, Calicut Medical College, for CMC Analytica. It is based on our own experience with one cross-sectional study and one case report, and on the guidelines above. It is not medical or legal advice, and it does not replace your institution's committees or your guide.</p></div>
<img src="{LOGO}" style="height:120px;margin-top:26px;display:block">
<p class="src" style="margin-top:14px">Part of the series "Before I Leave Med School: Research". Read the full articles on medinn.in.</p>''',top='REFERENCES · A CMC ANALYTICA GUIDE'))
open('guide.html','w').write(f'<!doctype html><meta charset="utf-8"><style>{CSS}</style>'+''.join(P))
print(len(P),'pages')
